<?php require 'config/config.php';$city=trim($_GET['city']??'');$max=(float)($_GET['max']??0);$sql="SELECT r.*,p.title,p.address,p.city FROM rooms r JOIN properties p ON p.id=r.property_id WHERE r.status='available'";$q=[];if($city){$sql.=' AND p.city LIKE ?';$q[]="%$city%";}if($max){$sql.=' AND r.rent<=?';$q[]=$max;}$s=db()->prepare($sql.' ORDER BY p.created_at DESC');$s->execute($q);$rooms=$s->fetchAll();$title='Find Rooms';require 'config/header.php';?><div class="head"><small>DISCOVER</small><h1>Rooms that fit your life</h1></div><form class="search"><input name="city" value="<?=e($city)?>" placeholder="City"><input name="max" type="number" value="<?=e($max?:'')?>" placeholder="Max monthly rent"><button class="btn">Search</button></form><div class="cards"><?php foreach($rooms as $r):?><article><div class="photo"><span><?=e(ucfirst($r['room_type']))?></span></div><div class="body"><small><?=e($r['city'])?></small><h3><?=e($r['title'])?> · Room <?=e($r['room_number'])?></h3><p><?=e($r['address'])?></p><strong><?=money($r['rent'])?> <i>/ month</i></strong><p>Advance: <?=money($r['deposit'])?></p><a class="btn" href="<?=BASE_URL?>/room.php?id=<?=$r['id']?>">View Room</a></div></article><?php endforeach;?></div><?php require 'config/footer.php';?>
